  A.legal={inputOptions,lawReviewCandidates,refreshProjectImpacts,applyLawCollectionResult,importLawSource,lawSourceInfo,ui:{registration:renderRegistration,annual:()=>'',registrationDetails:renderRegistrationDetails,annualDetails:renderAnnual},projectRegistrationErrors,applyProjectRegistration,saveNotice,registrationStatusLabel,validateRegistrationRecord,saveRegistrationInfo,registrationEligibility,registrationRequirements,validateRegistrationApplication,registrationAttachmentDefinitions,registrationDeadlines,reportingEligibility,validatePermit,permitCompleteness,validateActionItem,validatePermitResult,validatePermitPlan,permitResults,resultPlans,reportPermitPlans,permitResultView,permitCanEdit,permitResultCategories,permitResultCategoryLabel,permitResultCategoryOptions,fundingRatios,presetItems,permitPresetDefaults,...(A.realMode?{}:{updateSamples}),relevantProjects,catalog:A.realMode?[]:catalog,permitCatalog,sources,initialize,isDate,addDays,initializationErrors,reportProjection,registrationFacts,annualRegistrationSummary,registrationId,normalizePermitRecord,reportCategories,permitGroups:Object.keys(groups)};
